H.background();
const w = H.W, h = H.H;
const a = Math.round(P.a), b = Math.round(P.b), c = Math.round(P.c), d = Math.round(P.d);
// product (ax+b)(cx+d)
const t2 = a * c, t1 = a * d + b * c, t0 = b * d;
H.text("Box method:  (a·x + b)(c·x + d)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("(" + a + "x + " + b + ")(" + c + "x + " + d + ") = " + t2 + "x² + " + t1 + "x + " + t0, 24, 52, { color: H.colors.sub, size: 14 });
// 2x2 area grid; columns = (ax, b), rows = (cx, d)
const gx = 70, gy = 90, cw = 150, ch = 95;
const cells = [
  { r: 0, col: 0, txt: (a * c) + "x²", fill: H.colors.accent },
  { r: 0, col: 1, txt: (b * c) + "x", fill: H.colors.good },
  { r: 1, col: 0, txt: (a * d) + "x", fill: H.colors.good },
  { r: 1, col: 1, txt: t0 + "", fill: H.colors.accent2 },
];
const lit = Math.floor((t * 1.2) % 4);
cells.forEach((cl, i) => {
  const x = gx + cl.col * cw, y = gy + cl.r * ch;
  H.rect(x, y, cw, ch, { fill: i === lit ? H.colors.warn : cl.fill, stroke: H.colors.ink, width: 2, radius: 6 });
  H.text(cl.txt, x + cw * 0.5, y + ch * 0.5 + 7, { color: H.colors.bg, size: 22, weight: 700, align: "center" });
});
// column / row headers
H.text(a + "x", gx + cw * 0.5, gy - 12, { color: H.colors.accent, size: 16, weight: 700, align: "center" });
H.text("+" + b, gx + cw * 1.5, gy - 12, { color: H.colors.accent, size: 16, weight: 700, align: "center" });
H.text(c + "x", gx - 22, gy + ch * 0.5 + 6, { color: H.colors.accent2, size: 16, weight: 700, align: "right" });
H.text("+" + d, gx - 22, gy + ch * 1.5 + 6, { color: H.colors.accent2, size: 16, weight: 700, align: "right" });
// combine like terms readout (the two x-terms add)
H.text("Like terms add:  " + (b * c) + "x + " + (a * d) + "x = " + t1 + "x", gx, gy + 2 * ch + 34, { color: H.colors.good, size: 14, weight: 600 });
H.text("Each box = area of one piece; sum the boxes = the product.", gx, gy + 2 * ch + 58, { color: H.colors.sub, size: 12 });
H.legend([{ label: "x² term", color: H.colors.accent }, { label: "x terms", color: H.colors.good }, { label: "constant", color: H.colors.accent2 }], w - 150, 90);
